// Package validation provides input validation functions for the Entire CLI.
// This package has no dependencies to avoid import cycles.
package validation

import (
	"errors"
	"fmt"
	"path/filepath"
	"regexp"
	"strings"
)

// pathSafeRegex matches alphanumeric characters, underscores, and hyphens only.
// Used to validate IDs that will be used in file paths.
var pathSafeRegex = regexp.MustCompile(`^[a-zA-Z0-9_-]+$`)

// ValidateSessionID validates that a session ID doesn't contain path separators
// or other unsafe characters for use in file paths.
// This prevents path traversal attacks when session IDs are used in file paths.
func ValidateSessionID(id string) error {
	if strings.TrimSpace(id) == "" {
		return errors.New("session ID cannot be empty")
	}
	if strings.HasPrefix(id, "-") {
		return fmt.Errorf("invalid session ID %q: starts with dash", id)
	}
	if strings.ContainsAny(id, "/\\") {
		return fmt.Errorf("invalid session ID %q: contains path separators", id)
	}
	// A bare "." or ".." is separator-free but still traverses when used as a
	// path segment (e.g. an agent that uses the ID as a directory component).
	if id == "." || id == ".." {
		return fmt.Errorf("invalid session ID %q: reserved path segment", id)
	}
	// Reject the Windows volume separator. A drive-relative path like "C:foo" is
	// separator-free and filepath.IsAbs reports it as non-absolute, yet
	// filepath.Join discards the base directory when the appended element
	// carries a volume name — escaping the intended directory on Windows.
	if strings.Contains(id, ":") {
		return fmt.Errorf("invalid session ID %q: contains volume separator", id)
	}
	// Reject glob metacharacters. Session IDs are interpolated into
	// filepath.Glob patterns in several places (agent transcript lookup,
	// session-state cleanup); "*"/"?"/"[" could match and act on unrelated files.
	if strings.ContainsAny(id, "*?[") {
=== grok lifecycle.go 50-110 ===
	}
	return time.Now()
}

// sessionRef resolves the transcript path. Every hook but session_start
// supplies transcriptPath outright, which is authoritative; only session_start
// needs the path derived from cwd + session id.
func (g *GrokAgent) sessionRef(ctx context.Context, in baseHookInput) string {
	if in.TranscriptPath != "" {
		return in.TranscriptPath
	}
	// cwd, not workspaceRoot. Grok names the session group after the working
	// directory exactly as given, and the two differ: workspaceRoot carries a
	// trailing slash where cwd does not. Encoding that slash yields a group
	// name ending in %2F, which no session directory matches. The trailing
	// separator is trimmed anyway so the fallback stays correct if only
	// workspaceRoot is present.
	cwd := strings.TrimRight(in.CWD, "/")
	if cwd == "" {
		cwd = strings.TrimRight(in.WorkspaceRoot, "/")
	}
	if cwd == "" || in.SessionID == "" {
		return ""
	}
	dir, err := g.GetSessionDir(cwd)
	if err != nil {
		logging.Warn(ctx, "grok: failed to resolve session dir", "err", err)
		return ""
	}
	return g.ResolveSessionFile(dir, in.SessionID)
}

func (g *GrokAgent) parseSessionStart(ctx context.Context, stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[sessionStartInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.SessionStart,
		SessionID:  raw.SessionID,
		SessionRef: g.sessionRef(ctx, raw.baseHookInput),
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

func (g *GrokAgent) parseTurnStart(stdin io.Reader) (*agent.Event, error) {
	raw, err := agent.ReadAndParseHookInput[userPromptSubmitInput](stdin)
	if err != nil {
		return nil, err
	}
	return &agent.Event{
		Type:       agent.TurnStart,
		SessionID:  raw.SessionID,
		SessionRef: raw.TranscriptPath,
		Prompt:     unwrapPrompt(raw.Prompt),
		Timestamp:  parseTime(raw.Timestamp),
	}, nil
}

// userQueryOpen and userQueryClose bracket the prompt in Grok's
// user_prompt_submit payload.
